# ============================================================
# STATISTICAL MYSTERY GAME
# ============================================================

library(shiny)
library(ggplot2)

# ------------------------------------------------------------
# GAME DATA
# ------------------------------------------------------------

rounds <- list(
  
  list(
    title = "Round 1: The Headline",
    
    evidence = list(
      "Newspaper article" =
        "BREAKTHROUGH DRUG BOOSTS CONCENTRATION BY 32%.",
      
      "Results table" =
        "Mean score before treatment: 64\n
         Mean score after treatment: 84",
      
      "Company claim" =
        "Nexora Labs claims concentration improved by 32%."
    ),
    
    question =
      "Does the results table support the company's claim of a
       32% improvement? Show how you reached your answer.",
    
    type = "numeric",
    
    correct_answer = 31.25,
    
    feedback =
      "The increase is 20 points. As a percentage of the original
       score, this is 20/64 x 100 = 31.25%, not 32%."
  ),
  
  
  list(
    title = "Round 2: Who Took Part?",
    
    evidence = list(
      "Sample" =
        "80 students were selected from a private university.",
      
      "Recruitment" =
        "Students volunteered after seeing an advertisement.",
      
      "Population" =
        "The company wants to make claims about all university students."
    ),
    
    question =
      "Give TWO reasons why the sample may not be representative
       of all university students.",
    
    type = "text",
    
    feedback =
      "Possible answers include volunteer bias, sampling bias,
       and the fact that students came from only one university."
  )
  
)


# ------------------------------------------------------------
# USER INTERFACE
# ------------------------------------------------------------

ui <- fluidPage(
  
  titlePanel("The Statistical Mystery"),
  
  sidebarLayout(
    
    sidebarPanel(
      
      h4("Investigation progress"),
      
      textOutput("progress"),
      
      br(),
      
      actionButton(
        "next_round",
        "Next round"
      ),
      
      br(),
      br(),
      
      textOutput("score")
      
    ),
    
    mainPanel(
      
      h2(textOutput("round_title")),
      
      hr(),
      
      h3("Evidence"),
      
      uiOutput("evidence"),
      
      hr(),
      
      h3("Your task"),
      
      textOutput("question"),
      
      br(),
      
      uiOutput("answer_input"),
      
      br(),
      
      actionButton(
        "submit",
        "Submit answer"
      ),
      
      br(),
      br(),
      
      uiOutput("feedback")
      
    )
  )
)


# ------------------------------------------------------------
# SERVER
# ------------------------------------------------------------

server <- function(input, output, session) {
  
  # Current round
  current_round <- reactiveVal(1)
  
  # Score
  score <- reactiveVal(0)
  
  # Whether answer has been submitted
  answer_submitted <- reactiveVal(FALSE)
  
  
  # ----------------------------------------------------------
  # ROUND TITLE
  # ----------------------------------------------------------
  
  output$round_title <- renderText({
    
    rounds[[current_round()]]$title
    
  })
  
  
  # ----------------------------------------------------------
  # PROGRESS
  # ----------------------------------------------------------
  
  output$progress <- renderText({
    
    paste(
      "Round",
      current_round(),
      "of",
      length(rounds)
    )
    
  })
  
  
  # ----------------------------------------------------------
  # SCORE
  # ----------------------------------------------------------
  
  output$score <- renderText({
    
    paste("Score:", score())
    
  })
  
  
  # ----------------------------------------------------------
  # EVIDENCE
  # ----------------------------------------------------------
  
  output$evidence <- renderUI({
    
    evidence <- rounds[[current_round()]]$evidence
    
    tagList(
      
      lapply(
        
        names(evidence),
        
        function(name) {
          
          wellPanel(
            
            h4(name),
            
            p(evidence[[name]])
            
          )
          
        }
        
      )
      
    )
    
  })
  
  
  # ----------------------------------------------------------
  # QUESTION
  # ----------------------------------------------------------
  
  output$question <- renderText({
    
    rounds[[current_round()]]$question
    
  })
  
  
  # ----------------------------------------------------------
  # ANSWER INPUT
  # ----------------------------------------------------------
  
  output$answer_input <- renderUI({
    
    round <- rounds[[current_round()]]
    
    if (round$type == "numeric") {
      
      numericInput(
        "answer",
        "Your answer:",
        value = NA,
        min = 0
      )
      
    } else {
      
      textAreaInput(
        "answer",
        "Your answer:",
        rows = 5,
        width = "100%"
      )
      
    }
    
  })
  
  
  # ----------------------------------------------------------
  # SUBMIT ANSWER
  # ----------------------------------------------------------
  
  observeEvent(input$submit, {
    
    round <- rounds[[current_round()]]
    
    if (round$type == "numeric") {
      
      if (
        !is.na(input$answer) &&
        abs(input$answer - round$correct_answer) < 0.5
      ) {
        
        score(score() + 1)
        
        output$feedback <- renderUI({
          
          div(
            
            class = "alert alert-success",
            
            strong("Correct! "),
            
            round$feedback
            
          )
          
        })
        
      } else {
        
        output$feedback <- renderUI({
          
          div(
            
            class = "alert alert-danger",
            
            strong("Not quite. "),
            
            round$feedback
            
          )
          
        })
        
      }
      
    } else {
      
      # For text answers we do not automatically mark them yet.
      
      output$feedback <- renderUI({
        
        div(
          
          class = "alert alert-info",
          
          strong("Good investigation. "),
          
          round$feedback
          
        )
        
      })
      
    }
    
    answer_submitted(TRUE)
    
  })
  
  
  # ----------------------------------------------------------
  # NEXT ROUND
  # ----------------------------------------------------------
  
  observeEvent(input$next_round, {
    
    if (current_round() < length(rounds)) {
      
      current_round(current_round() + 1)
      
      answer_submitted(FALSE)
      
      output$feedback <- renderUI(NULL)
      
    } else {
      
      output$feedback <- renderUI({
        
        div(
          
          class = "alert alert-success",
          
          h3("Case closed!"),
          
          p(
            paste(
              "You completed the investigation with a score of",
              score()
            )
          )
          
        )
        
      })
      
    }
    
  })
  
}


# ------------------------------------------------------------
# RUN APP
# ------------------------------------------------------------

shinyApp(
  ui = ui,
  server = server
)
